 * Declares read access to removed-component lifecycle records.
 *
 * Each run returns the entities whose component was removed since the
 * system's previous run (removals are applied when commands are). Records are
 * kept until every system that reads them has run, so a reader in a schedule
 * ticked less often than the one that removes (rendering after several fixed
 * updates) still sees every removal. A system skipped by its run conditions
 * keeps its position, like `added`/`changed`, and sees the removals when it
 * runs again. Each log is capped at `Runtime.streamCapacity` entries; drops
 * show up as `missed` reads in the debug trace. Systems usually pair this
 * with host cleanup such as removing renderer-owned nodes. {@link readDespawned}
 * complements this for whole-entity teardown.
 *
 * @example
 * ```ts
 * const DestroyRenderNodesSystem = Game.System("DestroyRenderNodes", {
 *   removed: {
 *     renderables: Game.System.readRemoved(Renderable)
 *   }
 * }, ({ removed }) => {
 *   for (const entityId of removed.renderables.all()) {
 *     // destroy host-owned node here
 *   }
 * })
 * ```
 */
export const readRemoved = <D extends Descriptor<"component", string, any>>(
  descriptor: D
): RemovedRead<D> => ({
  descriptor
})

/**
 * Declares read access to relation-mutation failure records.
 */
export const readRelationFailures = <R extends Relation.Relation.Any>(
  relation: R
): RelationFailureRead<R> => ({
  relation
})

/**
 * Declares read access to despawned-entity lifecycle records.
 *
 * Each run returns the entities despawned since the system's previous run.
 * Records are retained like {@link readRemoved} records. Use it when host-owned state must be destroyed even if no single removed
 * component is the canonical trigger. {@link readRemoved} is often used
 * alongside this in authoritative host mirrors.
 *
 * @example
 * ```ts
 * const DestroyNodesSystem = Game.System("DestroyNodes", {
 *   despawned: {
 *     entities: Game.System.readDespawned()
 *   }
 * }, ({ despawned }) => {
 *   for (const entityId of despawned.entities.all()) {
 *     // destroy host-owned node here
 *   }
 * })
 * ```
 */
export const readDespawned = (): DespawnedRead => ({
  kind: "despawned"
})

/**
 * A read-only lifecycle stream of entity ids for one removed component.
 */
export interface RemovedReadView<S extends Schema.Any, Root = unknown> {
  all(): ReadonlyArray<import("./Entity.ts").EntityId<S, Root>>
}

/**
 * A read-only lifecycle stream of despawned entity ids.
 */
export interface DespawnedReadView<S extends Schema.Any, Root = unknown> {

) => Entity.EntityId<S, Root>
/**
 * Queues an entity removal.
 */
readonly despawn: (entity: Entity.EntityId<S, Root>) => void
/**
 * Queues removal of every entity owned by one lifetime scope.
 */
readonly despawnScope: (scope: EntityScope.EntityScope<string, Root>) => void
/**
 * Queues a component removal on an existing entity.
 */
readonly remove: <D extends Extract<Schema.Components<S>[keyof Schema.Components<S>], Descriptor<"component", string, any>>>(
  entity: Entity.EntityId<S, Root>,
  descriptor: D
) => Entity.EntityId<S, Root>
/**
 * Queues one live relation mutation for deferred application.
 */
readonly relate: <R extends Extract<Schema.Relations<S>[keyof Schema.Relations<S>], Relation.Relation.Any>>(

const makeRemovedReadView = (descriptor: Descriptor<"component", string, any>, reader: ReaderState): RemovedReadView<S, Root> => {
  const ordinal = world.ordinalOf(descriptor)
  return {
    all() {
      return world.removedSince(ordinal, reader.since).map(entityId)
    }
  }
}

const makeDespawnedReadView = (reader: ReaderState): DespawnedReadView<S, Root> => ({
  all() {
    return world.despawnedSince(reader.since).map(entityId)
  }
})

const registerStreamReader = (system: SystemDefinition<any, any, any>, reader: ReaderState): void => {
  if (debugEnabled) streamReaders.set(reader, { system: system.name, reader })
  const spec = system.spec
  for (const access of Object.values(spec.events as Record<string, { readonly mode: string; readonly descriptor: Descriptor.Any }>)) {
    if (access.mode === "read") events.register(access.descriptor.key, reader)
  }
  for (const access of Object.values(spec.transitionEvents as Record<string, { readonly machine: Machine.StateMachine.Any }>)) {
    transitionEvents.register(access.machine.key, reader)
  }
  for (const access of Object.values(spec.relationFailures as Record<string, { readonly relation: Relation.Relation.Any }>)) {
    relationFailures.register(access.relation.key, reader)
  }
  // Removed/despawned reads use the change-detection cursor, so a system
  // skipped by its run conditions keeps them, like `added`/`changed`.
  for (const access of Object.values(spec.removed as Record<string, { readonly descriptor: Descriptor<"component", string, any> }>)) {
    world.registerRemovedReader(world.ordinalOf(access.descriptor), reader)
  }
  if (Object.keys(spec.despawned).length > 0) world.registerDespawnedReader(reader)
}

/** Gated copies (`Schedule.when`) share the state of the system they copy. */
const stateKey = (system: SystemDefinition<any, any, any>): SystemDefinition<any, any, any> => system.base ?? system

const slotOf = (system: SystemDefinition<any, any, any>, holdsStreams: boolean): SystemSlot => {
  let slot = slots.get(stateKey(system))
  if (!slot) {
    const reader: ReaderState = { since: 0, lastRun: 0, streamSince: 0, streamLastRun: 0, registeredAt: world.currentTick() }
    slot = { context: makeContext(system, reader), reader }
    slots.set(stateKey(system), slot)
    if (holdsStreams) registerStreamReader(system, slot.reader)
  }
  return slot
}

/**
 * Evaluates a declared read-only projection without running a schedule.
 * Like a system, an inspector sees `added`/`changed`/removed records made
 * since its previous evaluation.
 */
const inspect = <const Selected extends Inspector.InspectorDefinition<any, any, Root, any, any>>(
  inspector: Selected
): Inspector.Inspector.Value<Selected> => {
  const { context, reader } = slotOf(inspector.system, false)
  reader.since = reader.lastRun
  reader.streamSince = reader.streamLastRun
  const value = inspector.read(context) as Inspector.Inspector.Value<Selected>
  reader.lastRun = world.advanceTick()
  reader.streamLastRun = reader.lastRun
  return value
}

const removeComponent = (id: number, descriptor: ComponentDescriptor): void => {
  const record = records.get(id)
  if (!record) {
    return
  }
  const ordinal = ordinalOf(descriptor)
  if (!has(record, ordinal)) {
    return
  }
  record.values[ordinal] = ABSENT
  members[ordinal]!.delete(record)
  bumpMembership(record, ordinal)
  appendLog(logFor(removedLogs, ordinal), id, tick)
  if (hooks !== undefined) hooks.removed(id, ordinal)

/**
 * Starts a new frame (one `runtime.tick(...)` call): log entries older than
 * the previous frame are dropped. Returns that boundary tick (entries at or
 * before it are gone), or `0` when nothing was dropped yet.
 */
const advanceFrame = (): number => {
  for (let ordinal = 0; ordinal < descriptors.length; ordinal++) {
    // Keep membership changes from the current and previous frame.
    const boundary = frameVersions[ordinal]!
    const versions = membershipVersions[ordinal]!
    let count = 0
    while (count < versions.length && versions[count]! <= boundary) count++
    if (count > 0) {
      versions.splice(0, count)
      membershipRecords[ordinal]!.splice(0, count)
      membershipFrom[ordinal] = boundary
    }
    frameVersions[ordinal] = componentVersions[ordinal]!
  }
  if (frameStart > 0) {
    for (const log of changedLogs) if (log) trimLog(log, frameStart)
    removedLogs.forEach((log, ordinal) => {
      if (log) trimHeldLog(log, frameStart, removedReaders[ordinal], lifecycleCapacity)
    })
    trimHeldLog(despawnedLog, frameStart, despawnedReaders, lifecycleCapacity)
    retainedAfter = frameStart
  }
  frameStart = tick
  return retainedAfter
}

const entriesSince = (log: TickLog | undefined, since: number): ReadonlyArray<number> => {
  if (log === undefined) return noSources

    version: 1,
    frame: frameCount,
    tick: world.currentTick(),
    entityCount: world.records.size,
    entities,
    resources: dumpedResources,
    machines: dumpedMachines,
    pendingCommands: pendingCommands.map((command, index) => ({ tag: command.tag, system: pendingOrigins[index] ?? "(unknown)" }))
  }
}

const streams = (): ReadonlyArray<Debug.StreamStatus> => {
  const result: Array<Debug.StreamStatus> = []
  const windowBoundary = world.retainedAfter()
  const inspectStore = (
    kind: Debug.StreamStatus["kind"],
    store: Streams.Streams<unknown>,
    names: ReadonlyMap<symbol, string>
  ): void => {
    for (const entry of store.inspect()) {
      let holder: { readonly system: string; readonly lastRun: number } | undefined
      const readers = entry.readers.map((cursor): Debug.StreamReaderStatus => {
        const known = streamReaders.get(cursor)
        const system = known?.system ?? "(unknown)"
        if (holder === undefined || cursor.streamLastRun < holder.lastRun) holder = { system, lastRun: cursor.streamLastRun }
        return {
          system,
          unread: store.since(entry.key, cursor.streamLastRun).length,
          lagged: known !== undefined && store.lagged(entry.key, known.reader.streamLastRun, known.reader.registeredAt)
        }
      })
      const heldByReader = entry.oldestTick !== undefined && entry.oldestTick <= windowBoundary
        && holder !== undefined && holder.lastRun < entry.oldestTick
      result.push({
        kind,
        stream: names.get(entry.key) ?? "(unknown)",
        size: entry.size,
        capacity: store.capacity,
        readers,
        heldBy: heldByReader ? holder!.system : undefined
      })
    }
  }
  inspectStore("event", events, debugNames!.events)
  inspectStore("transitionEvent", transitionEvents as Streams.Streams<unknown>, debugNames!.machines)
  inspectStore("relationFailure", relationFailures as Streams.Streams<unknown>, debugNames!.relations)
  return result
}

def Array.new(-T: Data, +d: Nat, +v: T) -> Array<T>:
  match d:
    case 0n:
      ALeaf{v}
    case 1n+p:
      ANode{[v : T^p], [v : T^p]}
